function minivanRoadTrip(times, k) {
  const n = times.length;
  const memo = new Map();

  function delay(i) {
    if (i >= n) {
      return 0;
    }
    if (i >= n - k - 1) {
      return times[i];
    }
    if (memo.has(i)) {
      return memo.get(i);
    }
    let minDelay = Infinity;
    for (let p = 1; p <= k + 1; p++) {
      minDelay = Math.min(minDelay, delay(i + p));
    }
    memo.set(i, times[i] + minDelay);
    return memo.get(i);
  }

  let minDelay = Infinity;
  for (let p = 0; p <= k; p++) {
    minDelay = Math.min(minDelay, delay(p));
  }
  return minDelay;
}

